    'flashcard',  -- exercise_type
    '[{"id":1,"word":"abandon","pos":"v","phonetic":"/əˈbændən/","phonetic_uk":"/əˈbændən/","phonetic_us":"/əˈbændən/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aba/aband/abandon__gb_2.mp3","definition_vi":"bỏ rơi, ruồng bỏ","definition_en":"to leave somebody, especially somebody you are responsible for, with no intention of returning","examples":[{"example_en":"[abandon] somebody The baby had been abandoned by its mother.","example_vi":"We should not abandon veterans.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aba/aband/abandon__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/7_abandon.jpg"},{"id":2,"word":"abolish","pos":"v","phonetic":"/əˈbɒlɪʃ/","phonetic_uk":"/əˈbɒlɪʃ/","phonetic_us":"/əˈbɒlɪʃ/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abo/aboli/abolish__gb_2.mp3","definition_vi":"cancel, revoke","definition_en":"to officially end a law, a system or an institution","examples":[{"example_en":"This tax should be abolished.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abo/aboli/abolish__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_abolish.jpg"},{"id":3,"word":"absolute","pos":"adj","phonetic":"/ˈæbsəluːt/","phonetic_uk":"/ˈæbsəluːt/","phonetic_us":"/ˈæbsəluːt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/absol/absolute__gb_1.mp3","definition_vi":"hoàn toàn","definition_en":"total and complete","examples":[{"example_en":"I''ve joined a class for [absolute] beginners.","example_vi":"a class for absolute beginners","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/absol/absolute__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_absolute.jpg"},{"id":4,"word":"absorb","pos":"v","phonetic":"/əbˈzɔːb/","phonetic_uk":"/əbˈzɔːb/","phonetic_us":"/əbˈzɔːb/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/absor/absorb__gb_2.mp3","definition_vi":"suck up; take up, take in","definition_en":"to take in a liquid, gas or other substance from the surface or space around","examples":[{"example_en":"[absorb] something Plants [absorb] carbon dioxide from the air.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/absor/absorb__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_absorb.jpg"},{"id":5,"word":"abstract","pos":"adj","phonetic":"/ˈæbstrækt/","phonetic_uk":"/ˈæbstrækt/","phonetic_us":"/ˈæbstrækt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/abstr/abstract__gb_5.mp3","definition_vi":"lý thuyết, trừu tượng","definition_en":"based on general ideas and not on any particular real person, thing or situation","examples":[{"example_en":"[abstract] knowledge/principles","example_vi":"abstract knowledge/principles","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/abstr/abstract__gb_5.mp3"}],"image_url":"/media/vocabs_media/img/6_abstract.jpg"},{"id":6,"word":"absurd","pos":"adj","phonetic":"/əbˈsɜːd/","phonetic_uk":"/əbˈsɜːd/","phonetic_us":"/əbˈsɜːd/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/absur/absurd__gb_1.mp3","definition_vi":"ngớ ngẩn, lố bịch","definition_en":"extremely silly; not logical and sensible","examples":[{"example_en":"That uniform makes the guards look [absurd].","example_vi":"That uniform makes the guards look absurd.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/abs/absur/absurd__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_absurd.jpg"},{"id":7,"word":"access","pos":"v","phonetic":"/ˈækses/","phonetic_uk":"/ˈækses/","phonetic_us":"/ˈækses/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/acces/access__gb_4.mp3","definition_vi":"tiếp cận, sử dụng","definition_en":"the opportunity or right to use something or to see somebody/something","examples":[{"example_en":"High-speed internet [access] has become a necessity.","example_vi":"The loft can be accessed by a ladder.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/acces/access__gb_4.mp3"}],"image_url":"/media/vocabs_media/img/5_access.jpg"},{"id":8,"word":"accommodate","pos":"v","phonetic":"/əˈkɒmədeɪt/","phonetic_uk":"/əˈkɒmədeɪt/","phonetic_us":"/əˈkɒmədeɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accom/accommodate__gb_1.mp3","definition_vi":"host guests; provide lodging; adapt oneself; give, bestow","definition_en":"to provide somebody with a room or place to sleep, live or sit","examples":[{"example_en":"The hotel can [accommodate] up to 500 guests.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accom/accommodate__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_accommodate.jpg"},{"id":9,"word":"accompany","pos":"v","phonetic":"/əˈkʌmpəni/","phonetic_uk":"/əˈkʌmpəni/","phonetic_us":"/əˈkʌmpəni/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accom/accompany__gb_1.mp3","definition_vi":"đồng hành, đi cùng, hộ tống","definition_en":"to travel or go somewhere with somebody/something","examples":[{"example_en":"[accompany] somebody/something + adv./prep","example_vi":"It is said that she will accompany him to his tour.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accom/accompany__gb_1.mp3"},{"example_en":"His wife accompanied him on the trip.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accom/accompany__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_accompany.jpg"},{"id":10,"word":"accuracy","pos":"n","phonetic":"/ˈækjərəsi/","phonetic_uk":"/ˈækjərəsi/","phonetic_us":"/ˈækjərəsi/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accur/accuracy__gb_1.mp3","definition_vi":"preciseness, exactness","definition_en":"the state of being exact or correct; the ability to do something with skill and without making mistakes","examples":[{"example_en":"They questioned the [accuracy] of the information in the file.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accur/accuracy__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_accuracy.jpg"},{"id":11,"word":"accuse","pos":"v","phonetic":"/əˈkjuːz/","phonetic_uk":"/əˈkjuːz/","phonetic_us":"/əˈkjuːz/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accus/accuse__gb_1.mp3","definition_vi":"buộc tội, tố cáo","definition_en":"to say that somebody has done something wrong or is guilty of something","examples":[{"example_en":"[accuse] somebody of something to [accuse] somebody of murder/a crime","example_vi":"They accused me of not setting aside enough time.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acc/accus/accuse__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_accuse.jpg"},{"id":12,"word":"acquire","pos":"v","phonetic":"/əˈkwaɪə(r)/","phonetic_uk":"/əˈkwaɪə(r)/","phonetic_us":"/əˈkwaɪə(r)/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acq/acqui/acquire__gb_2.mp3","definition_vi":"thu được, đạt được","definition_en":"to gain something by your own efforts, ability or behaviour","examples":[{"example_en":"She has acquired a good knowledge of English.","example_vi":"He acquired the firm in 2008.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acq/acqui/acquire__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_acquire.jpg"},{"id":13,"word":"acquisition","pos":"n","phonetic":"/ˌækwɪˈzɪʃn/","phonetic_uk":"/ˌækwɪˈzɪʃn/","phonetic_us":"/ˌækwɪˈzɪʃn/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acq/acqui/acquisition__gb_1.mp3","definition_vi":"sự giành được, thu được, đạt được (kiến thức, kĩ năng)","definition_en":"the act of getting something, especially knowledge, a skill, etc.","examples":[{"example_en":"theories of child language [acquisition]","example_vi":"eLearning has gained acceptance as an effective means for knowledge acquisition.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acq/acqui/acquisition__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_acquisition.jpg"},{"id":14,"word":"activate","pos":"v","phonetic":"/ˈæktɪveɪt/","phonetic_uk":"/ˈæktɪveɪt/","phonetic_us":"/ˈæktɪveɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/act/activ/activate__gb_1.mp3","definition_vi":"kích hoạt","definition_en":"to make something such as a device or chemical process start working","examples":[{"example_en":"The burglar alarm is activated by movement.","example_vi":"The burglar alarm is activated by movement.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/act/activ/activate__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_activate.jpg"},{"id":15,"word":"acute","pos":"adj","phonetic":"/əˈkjuːt/","phonetic_uk":"/əˈkjuːt/","phonetic_us":"/əˈkjuːt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acu/acute/acute__gb_1.mp3","definition_vi":"nhanh nhạy, sắc sảo","definition_en":"very serious or severe","examples":[{"example_en":"There is an [acute] shortage of water.","example_vi":"He is an acute observer of the social scene.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/acu/acute/acute__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_acute.jpg"},{"id":16,"word":"adapt","pos":"v","phonetic":"/əˈdæpt/","phonetic_uk":"/əˈdæpt/","phonetic_us":"/əˈdæpt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ada/adapt/adapt__gb_2.mp3","definition_vi":"thích nghi (với môi trường...)","definition_en":"to change your behaviour in order to deal more successfully with a new situation","examples":[{"example_en":"It''s amazing how soon you [adapt].","example_vi":"It''s amazing how soon you adapt.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ada/adapt/adapt__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_adapt.jpg"},{"id":17,"word":"address","pos":"v","phonetic":"/əˈdres/","phonetic_uk":"/əˈdres/","phonetic_us":"/əˈdres/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/add/addre/address__gb_3.mp3","definition_vi":"phân tích và đề xuất cách giải quyết một vấn đề nào đó","definition_en":"details of where somebody lives or works and where letters, etc. can be sent","examples":[{"example_en":"What''s your name and [address]?","example_vi":"We must address ourselves to the problem of both material and spiritual civilization.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/add/addre/address__gb_3.mp3"}],"image_url":"/media/vocabs_media/img/6_address2.jpg"},{"id":18,"word":"adequate","pos":"adj","phonetic":"/ˈædɪkwət/","phonetic_uk":"/ˈædɪkwət/","phonetic_us":"/ˈædɪkwət/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ade/adequ/adequate__gb_3.mp3","definition_vi":"đủ, đầy đủ","definition_en":"enough in quantity, or good enough in quality, for a particular purpose or need","examples":[{"example_en":"They''ll need an [adequate] supply of hot water.","example_vi":"We have an adequate supply of firewood to last the winter.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ade/adequ/adequate__gb_3.mp3"}],"image_url":"/media/vocabs_media/img/5_adequate.jpg"},{"id":19,"word":"adhere","pos":"v","phonetic":"/ədˈhɪə(r)/","phonetic_uk":"/ədˈhɪə(r)/","phonetic_us":"/ədˈhɪə(r)/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adh/adher/adhere__gb_1.mp3","definition_vi":"stick to, cling to; be devoted to (an idea, group, etc.)","definition_en":"to stick to something","examples":[{"example_en":"Once in the bloodstream, the bacteria [adhere] to the surface of the red cells.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adh/adher/adhere__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_adhere.jpg"},{"id":20,"word":"adjacent","pos":"adj","phonetic":"/əˈdʒeɪsnt/","phonetic_uk":"/əˈdʒeɪsnt/","phonetic_us":"/əˈdʒeɪsnt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adj/adjac/adjacent__gb_1.mp3","definition_vi":"kế bên, gần","definition_en":"next to something","examples":[{"example_en":"The planes landed on [adjacent] runways.","example_vi":"The planes landed on adjacent runways.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adj/adjac/adjacent__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_adjacent.jpg"},{"id":21,"word":"adjust","pos":"v","phonetic":"/əˈdʒʌst/","phonetic_uk":"/əˈdʒʌst/","phonetic_us":"/əˈdʒʌst/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adj/adjus/adjust__gb_2.mp3","definition_vi":"điều chỉnh, làm cho thích hợp","definition_en":"to change something slightly to make it more suitable for a new set of conditions or to make it work better","examples":[{"example_en":"[adjust] something Watch out for sharp bends and [adjust] your speed accordingly.","example_vi":"They''ll be fine—they just need time to adjust.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adj/adjus/adjust__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_adjust.jpg"},{"id":22,"word":"adolescent","pos":"n","phonetic":"/ˌædəˈlesnt/","phonetic_uk":"/ˌædəˈlesnt/","phonetic_us":"/ˌædəˈlesnt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ado/adole/adolescent__gb_1.mp3","definition_vi":"thanh niên","definition_en":"a young person who is developing from a child into an adult","examples":[{"example_en":"adolescents between the ages of 13 and 18 and the problems they face","example_vi":"Adolescents nowadays have problems that are different from ours.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ado/adole/adolescent__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_adolescent.jpg"},{"id":23,"word":"adopt","pos":"v","phonetic":"/əˈdɒpt/","phonetic_uk":"/əˈdɒpt/","phonetic_us":"/əˈdɒpt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ado/adopt/adopt__gb_1.mp3","definition_vi":"áp dụng (một phương pháp, một cách nhìn mới, ...)","definition_en":"to take somebody else’s child into your family and become its legal parent(s)","examples":[{"example_en":"a campaign to encourage childless couples to [adopt]","example_vi":"The new tax would force companies to adopt energy-saving measures.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ado/adopt/adopt__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_adopt.jpg"},{"id":24,"word":"advocate","pos":"v","phonetic":"/ˈædvəkət/","phonetic_uk":"/ˈædvəkət/","phonetic_us":"/ˈædvəkət/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adv/advoc/advocate__gb_2.mp3","definition_vi":"ủng hộ, tán thành","definition_en":"a person who supports or speaks in favour of somebody or of a public plan or action","examples":[{"example_en":"[advocate] for something/somebody an [advocate] for hospital workers","example_vi":"The group does not advocate the use of violence.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/adv/advoc/advocate__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/6_advocate.gif"},{"id":25,"word":"aesthetic","pos":"adj","phonetic":"/iːsˈθetɪk/","phonetic_uk":"/iːsˈθetɪk/","phonetic_us":"/iːsˈθetɪk/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aes/aesth/aesthetic__gb_1.mp3","definition_vi":"(thuộc) mỹ học, thẩm mỹ","definition_en":"connected with beauty and art and the understanding of beautiful things","examples":[{"example_en":"the [aesthetic] appeal of the songs","example_vi":"an aesthetic appreciation of the landscape","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aes/aesth/aesthetic__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_aesthetic.jpg"},{"id":26,"word":"affect","pos":"v","phonetic":"/əˈfekt/","phonetic_uk":"/əˈfekt/","phonetic_us":"/əˈfekt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aff/affec/affect__gb_3.mp3","definition_vi":"ảnh hưởng đến, tác động đến","definition_en":"to produce a change in somebody/something","examples":[{"example_en":"How will these changes [affect] us?","example_vi":"Nothing you say will affect my decision.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aff/affec/affect__gb_3.mp3"}],"image_url":"/media/vocabs_media/img/5_affect.jpg"},{"id":27,"word":"allocate","pos":"v","phonetic":"/ˈæləkeɪt/","phonetic_uk":"/ˈæləkeɪt/","phonetic_us":"/ˈæləkeɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/all/alloc/allocate__gb_1.mp3","definition_vi":"ration; allot, set aside; designate a portion of system resources for a particular task or operation (Computers)","definition_en":"to give something officially to somebody/something for a particular purpose","examples":[{"example_en":"[allocate] something (for something) A large sum has been allocated for buying new books for the library.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/all/alloc/allocate__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_allocate.png"},{"id":28,"word":"alter","pos":"v","phonetic":"/ˈɔːltə(r)/","phonetic_uk":"/ˈɔːltə(r)/","phonetic_us":"/ˈɔːltə(r)/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/alt/alter/alter__gb_1.mp3","definition_vi":"thay đổi; làm cho cái gì đó thay đổi","definition_en":"to become different; to make somebody/something different","examples":[{"example_en":"Prices have not altered significantly this year.","example_vi":"Prices did not alter significantly during 2007.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/alt/alter/alter__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_alter.jpg"},{"id":29,"word":"alternative","pos":"n","phonetic":"/ɔːlˈtɜːnətɪv/","phonetic_uk":"/ɔːlˈtɜːnətɪv/","phonetic_us":"/ɔːlˈtɜːnətɪv/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/alt/alter/alternative__gb_3.mp3","definition_vi":"sự lựa chọn","definition_en":"that can be used instead of something else","examples":[{"example_en":"The road was closed so we had to find an [alternative] route.","example_vi":"We had no alternative but to go forward.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/alt/alter/alternative__gb_3.mp3"}],"image_url":"/media/vocabs_media/img/5_alternative.jpg"},{"id":30,"word":"analogy","pos":"n","phonetic":"/əˈnælədʒi/","phonetic_uk":"/əˈnælədʒi/","phonetic_us":"/əˈnælədʒi/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ana/analo/analogy__gb_2.mp3","definition_vi":"sự so sánh những đặc điểm tương tự; sự tương tự, sự giống nhau","definition_en":"a comparison of one thing with another thing that has similar features; a feature that is similar","examples":[{"example_en":"[analogy] (between A and B) The teacher drew an [analogy] between the human heart and a pump.","example_vi":"The teacher drew an analogy between the human heart and a pump.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ana/analo/analogy__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/6_analogy.jpg"},{"id":31,"word":"analyse","pos":"v","phonetic":"/ˈænəlaɪz/","phonetic_uk":"/ˈænəlaɪz/","phonetic_us":"/ˈænəlaɪz/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ana/analy/analyse__gb_6.mp3","definition_vi":"phân tích","definition_en":"to examine the nature or structure of something, especially by separating it into its parts, in order to understand or explain it","examples":[{"example_en":"[analyse] something The job involves collecting and analysing data.","example_vi":"The job involves gathering and analysing data.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ana/analy/analyse__gb_6.mp3"}],"image_url":"/media/vocabs_media/img/5_analyse.jpg"},{"id":32,"word":"anonymous","pos":"adj","phonetic":"/əˈnɒnɪməs/","phonetic_uk":"/əˈnɒnɪməs/","phonetic_us":"/əˈnɒnɪməs/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ano/anony/anonymous__gb_1.mp3","definition_vi":"giấu tên, ẩn danh","definition_en":"with a name that is not known or that is not made public","examples":[{"example_en":"an [anonymous] donor","example_vi":"an anonymous donor","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ano/anony/anonymous__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_anonymous.jpg"},{"id":33,"word":"anticipate","pos":"v","phonetic":"/ænˈtɪsɪpeɪt/","phonetic_uk":"/ænˈtɪsɪpeɪt/","phonetic_us":"/ænˈtɪsɪpeɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ant/antic/anticipate__gb_1.mp3","definition_vi":"đoán trước, liệu trước","definition_en":"to expect something","examples":[{"example_en":"[anticipate] something We don''t [anticipate] any major problems.","example_vi":"We don''t anticipate any major problems.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ant/antic/anticipate__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_anticipate.jpg"},{"id":34,"word":"apparatus","pos":"n","phonetic":"/ˌæpəˈreɪtəs/","phonetic_uk":"/ˌæpəˈreɪtəs/","phonetic_us":"/ˌæpəˈreɪtəs/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appar/apparatus__gb_1.mp3","definition_vi":"dụng cụ, thiết bị cho một hoạt động","definition_en":"the tools or other pieces of equipment that are needed for a particular activity or task","examples":[{"example_en":"a piece of laboratory [apparatus]","example_vi":"a piece of laboratory apparatus","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appar/apparatus__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_apparatus.jpg"},{"id":35,"word":"appeal","pos":"v","phonetic":"/əˈpiːl/","phonetic_uk":"/əˈpiːl/","phonetic_us":"/əˈpiːl/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appea/appeal__gb_1.mp3","definition_vi":"hấp dẫn, lôi cuốn","definition_en":"a deeply felt request for money, help or information that is needed immediately, especially one made by a charity or by the police","examples":[{"example_en":"[appeal] for something to launch a TV [appeal] for donations to the charity","example_vi":"The idea of a vacation appeals to me.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appea/appeal__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_appeal.jpg"},{"id":36,"word":"appealing","pos":"adj","phonetic":"/əˈpiːlɪŋ/","phonetic_uk":"/əˈpiːlɪŋ/","phonetic_us":"/əˈpiːlɪŋ/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appea/appealing__gb_1.mp3","definition_vi":"hấp dẫn, thú vị","definition_en":"attractive or interesting","examples":[{"example_en":"Spending the holidays in Britain wasn''t a prospect that I found particularly [appealing].","example_vi":"Spending the holidays in Britain wasn''t a prospect that I found particularly appealing.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appea/appealing__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_appealing.jpg"},{"id":37,"word":"appetite","pos":"n","phonetic":"/ˈæpɪtaɪt/","phonetic_uk":"/ˈæpɪtaɪt/","phonetic_us":"/ˈæpɪtaɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appet/appetite__gb_1.mp3","definition_vi":"desire, hunger","definition_en":"physical desire for food","examples":[{"example_en":"He suffered from headaches and loss of [appetite].","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appet/appetite__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_appetite.jpg"},{"id":38,"word":"appreciate","pos":"v","phonetic":"/əˈpriːʃieɪt/","phonetic_uk":"/əˈpriːʃieɪt/","phonetic_us":"/əˈpriːʃieɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appre/appreciate__gb_1.mp3","definition_vi":"tăng giá trị/lên giá (hàng hoá...) theo thời gian","definition_en":"to recognize the good qualities of somebody/something","examples":[{"example_en":"Over the years he came to [appreciate] the beauty and tranquillity of the river.","example_vi":"Their investments have appreciated over the years.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appre/appreciate__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_appreciate.jpg"},{"id":39,"word":"appropriate","pos":"adj","phonetic":"/əˈprəʊpriət/","phonetic_uk":"/əˈprəʊpriət/","phonetic_us":"/əˈprəʊpriət/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appro/appropriate__gb_4.mp3","definition_vi":"thích hợp, thích đáng","definition_en":"suitable, acceptable or correct for the particular circumstances","examples":[{"example_en":"an [appropriate] response/measure/method","example_vi":"It seems that an apology is appropriate in this situation.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/app/appro/appropriate__gb_4.mp3"}],"image_url":"/media/vocabs_media/img/5_appropriate.jpg"},{"id":40,"word":"arbitrary","pos":"adj","phonetic":"/ˈɑːbɪtrəri/","phonetic_uk":"/ˈɑːbɪtrəri/","phonetic_us":"/ˈɑːbɪtrəri/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/arb/arbit/arbitrary__gb_1.mp3","definition_vi":"wanton, reckless; uncontrolled, unrestricted; unreasonable, unsupported","definition_en":"not seeming to be based on a reason, system or plan and sometimes seeming unfair","examples":[{"example_en":"The choice of players for the team seemed completely [arbitrary].","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/arb/arbit/arbitrary__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_arbitrary.jpg"},{"id":41,"word":"articulate","pos":"v","phonetic":"/ɑːˈtɪkjuleɪt/","phonetic_uk":"/ɑːˈtɪkjuleɪt/","phonetic_us":"/ɑːˈtɪkjuleɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/art/artic/articulate__gb_1.mp3","definition_vi":"diễn đạt suy nghĩ/cảm xúc một cách rõ ràng bằng lời","definition_en":"to express or explain your thoughts or feelings clearly in words","examples":[{"example_en":"She struggled to [articulate] her thoughts.","example_vi":"She struggled to articulate her thoughts.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/art/artic/articulate__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_articulate.jpg"},{"id":42,"word":"artificial","pos":"adj","phonetic":"/ˌɑːtɪˈfɪʃl/","phonetic_uk":"/ˌɑːtɪˈfɪʃl/","phonetic_us":"/ˌɑːtɪˈfɪʃl/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/art/artif/artificial__gb_1.mp3","definition_vi":"not genuine, simulated","definition_en":"made or produced to copy something natural; not real","examples":[{"example_en":"an [artificial] limb/flower/sweetener/fertilizer","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/art/artif/artificial__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_artificial.jpg"},{"id":43,"word":"aspect","pos":"n","phonetic":"/ˈæspekt/","phonetic_uk":"/ˈæspekt/","phonetic_us":"/ˈæspekt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/asp/aspec/aspect__gb_2.mp3","definition_vi":"point of view, facet; appearance, outlook; direction; action of a verb without relating to its time","definition_en":"a particular part or feature of a situation, an idea, a problem, etc.; a way in which it may be considered","examples":[{"example_en":"[aspect] of something The book aims to cover all aspects of city life.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/asp/aspec/aspect__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_aspect.jpg"},{"id":44,"word":"assert","pos":"v","phonetic":"/əˈsɜːt/","phonetic_uk":"/əˈsɜːt/","phonetic_us":"/əˈsɜːt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/asser/assert__gb_1.mp3","definition_vi":"state, declare; insist on","definition_en":"to state clearly and definitely that something is true","examples":[{"example_en":"[assert] that… She continued to [assert] that she was innocent.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/asser/assert__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_assert.png"},{"id":45,"word":"assess","pos":"v","phonetic":"/əˈses/","phonetic_uk":"/əˈses/","phonetic_us":"/əˈses/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/asses/assess__gb_2.mp3","definition_vi":"đánh giá","definition_en":"to make a judgement about the nature or quality of somebody/something","examples":[{"example_en":"[assess] somebody/something Accurately assessing environmental impacts is very complex.","example_vi":"After the hurricane, officials assessed the town''s need for aid.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/asses/assess__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_assess.jpg"},{"id":46,"word":"asset","pos":"n","phonetic":"/ˈæset/","phonetic_uk":"/ˈæset/","phonetic_us":"/ˈæset/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/asset/asset__gb_3.mp3","definition_vi":"của cải, tài sản","definition_en":"a person or thing that is valuable or useful to somebody/something","examples":[{"example_en":"In his job, patience is an invaluable [asset].","example_vi":"Her lips are her best asset.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/asset/asset__gb_3.mp3"}],"image_url":"/media/vocabs_media/img/5_asset.jpg"},{"id":47,"word":"assignment","pos":"n","phonetic":"/əˈsaɪnmənt/","phonetic_uk":"/əˈsaɪnmənt/","phonetic_us":"/əˈsaɪnmənt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/assig/assignment__gb_2.mp3","definition_vi":"task, mission; transfer of ownership or rights","definition_en":"a task or piece of work that somebody is given to do, usually as part of their job or studies","examples":[{"example_en":"Students are required to complete all homework assignments.","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/assig/assignment__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_assignment.jpg"},{"id":48,"word":"assist","pos":"v","phonetic":"/əˈsɪst/","phonetic_uk":"/əˈsɪst/","phonetic_us":"/əˈsɪst/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/assis/assist__gb_1.mp3","definition_vi":"giúp đỡ, hỗ trợ","definition_en":"to help somebody to do something","examples":[{"example_en":"Anyone willing to [assist] can contact this number.","example_vi":"Federal agents are assisting with the investigation.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/assis/assist__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_assist.jpg"},{"id":49,"word":"associate","pos":"v","phonetic":"/əˈsəʊsieɪt/","phonetic_uk":"/əˈsəʊsieɪt/","phonetic_us":"/əˈsəʊsieɪt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/assoc/associate__gb_2.mp3","definition_vi":"gắn kết, kết nối (những ý nghĩ về người hoặc vật)","definition_en":"to make a connection between people or things in your mind","examples":[{"example_en":"[associate] somebody/something with somebody/something I always [associate] the smell of baking with my childhood.","example_vi":"I always associate the smell of baking with my childhood.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/ass/assoc/associate__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/7_associate.png"},{"id":50,"word":"asylum","pos":"n","phonetic":"/əˈsaɪləm/","phonetic_uk":"/əˈsaɪləm/","phonetic_us":"/əˈsaɪləm/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/asy/asylu/asylum__gb_1.mp3","definition_vi":"shelter, refuge; hospital for the mentally ill","definition_en":"protection that a government gives to people who have left their own country, usually because they were in danger for political reasons","examples":[{"example_en":"to seek/apply for/be granted [asylum]","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/asy/asylu/asylum__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_asylum.jpg"},{"id":51,"word":"atmosphere","pos":"n","phonetic":"/ˈætməsfɪə(r)/","phonetic_uk":"/ˈætməsfɪə(r)/","phonetic_us":"/ˈætməsfɪə(r)/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/atm/atmos/atmosphere__gb_1.mp3","definition_vi":"bầu không khí (nghĩa bóng)","definition_en":"the mixture of gases that surrounds the earth","examples":[{"example_en":"Wind power doesn''t release carbon dioxide into the [atmosphere].","example_vi":"This restaurant has a warm atmosphere.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/atm/atmos/atmosphere__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_atmosphere.jpg"},{"id":52,"word":"attitude","pos":"n","phonetic":"/ˈætɪtjuːd/","phonetic_uk":"/ˈætɪtjuːd/","phonetic_us":"/ˈætɪtjuːd/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/att/attit/attitude__gb_2.mp3","definition_vi":"thái độ, quan điểm","definition_en":"the way that you think and feel about somebody/something; the way that you behave towards somebody/something that shows how you think and feel","examples":[{"example_en":"[attitude] towards somebody/something These societies have to change their attitudes towards women.","example_vi":"It''s a personal matter whether you choose stock from this company or from that because in the end it''s an attitude of mind.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/att/attit/attitude__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/5_attitude.jpg"},{"id":53,"word":"attribute","pos":"n","phonetic":"/ˈætrɪbjuːt/","phonetic_uk":"/ˈætrɪbjuːt/","phonetic_us":"/ˈætrɪbjuːt/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/att/attri/attribute__gb_2.mp3","definition_vi":"đức tính, đặc tính","definition_en":"a quality or feature of somebody/something","examples":[{"example_en":"Patience is one of the most important attributes in a teacher.","example_vi":"Patience is one of the most important attributes in a teacher.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/att/attri/attribute__gb_2.mp3"}],"image_url":"/media/vocabs_media/img/7_attribute2.jpg"},{"id":54,"word":"authentic","pos":"adj","phonetic":"/ɔːˈθentɪk/","phonetic_uk":"/ɔːˈθentɪk/","phonetic_us":"/ɔːˈθentɪk/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aut/authe/authentic__gb_1.mp3","definition_vi":"đích thực; xác thực","definition_en":"known to be real and what somebody claims it is and not a copy","examples":[{"example_en":"I don''t know if the painting is [authentic].","example_vi":"I don''t know if the painting is authentic.","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aut/authe/authentic__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/7_authentic.jpg"},{"id":55,"word":"automatic","pos":"adj","phonetic":"/ˌɔːtəˈmætɪk/","phonetic_uk":"/ˌɔːtəˈmætɪk/","phonetic_us":"/ˌɔːtəˈmætɪk/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aut/autom/automatic__gb_1.mp3","definition_vi":"operating by itself; unintentional","definition_en":"having controls that work without needing a person to operate them","examples":[{"example_en":"[automatic] doors","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aut/autom/automatic__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/5_automatic.jpg"},{"id":56,"word":"autonomy","pos":"n","phonetic":"/ɔːˈtɒnəmi/","phonetic_uk":"/ɔːˈtɒnəmi/","phonetic_us":"/ɔːˈtɒnəmi/","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aut/auton/autonomy__gb_1.mp3","definition_vi":"independence","definition_en":"the freedom for a country, a region or an organization to govern itself independently","examples":[{"example_en":"a campaign in Wales for greater [autonomy]","example_vi":"","audio":"https://www.oxfordlearnersdictionaries.com/media/english/uk_pron/a/aut/auton/autonomy__gb_1.mp3"}],"image_url":"/media/vocabs_media/img/6_autonomy.jpg"},{"id":57,"word":"abet","pos":"v","phonetic":"/əˈbet/","phonetic_uk":"/əˈbet/","phonetic_us":"/əˈbet/","audio":null,"definition_vi":"xúi giục","definition_en":"","examples":[{"example_en":"He was abetted in the deception by his wife.","example_vi":"He was abetted in the deception by his wife.","audio":null}],"image_url":"/media/vocabs_media/img/7_abet.jpg"},{"id":58,"word":"abhor","pos":"v","phonetic":"/əbˈhɔːr/","phonetic_uk":"/əbˈhɔːr/","phonetic_us":"/əbˈhɔːr/","audio":null,"definition_vi":"ghê tởm; ghét cay ghét đắng","definition_en":"","examples":[{"example_en":"I [abhor] all forms of racism.","example_vi":"I abhor all forms of racism.","audio":null}],"image_url":"/media/vocabs_media/img/6_abhor.jpg"},{"id":59,"word":"abject","pos":"adj","phonetic":"/ˈæbdʒekt/","phonetic_uk":"/ˈæbdʒekt/","phonetic_us":"/ˈæbdʒekt/","audio":null,"definition_vi":"khốn khổ và hết hy vọng","definition_en":"","examples":[{"example_en":"[abject] poverty/misery/failure","example_vi":"abject poverty/misery/failure","audio":null}],"image_url":"/media/vocabs_media/img/7_abject.jpg"},{"id":60,"word":"abridge","pos":"v","phonetic":"/əˈbrɪdʒ/","phonetic_uk":"/əˈbrɪdʒ/","phonetic_us":"/əˈbrɪdʒ/","audio":null,"definition_vi":"rút ngắn lại, cắt bớt (sách, vở kịch,...)","definition_en":"","examples":[{"example_en":"She has been asked to [abridge] the novel for radio.","example_vi":"She has been asked to abridge the novel for radio.","audio":null}],"image_url":"/media/vocabs_media/img/6_abridge.jpg"},{"id":61,"word":"abrogate","pos":"v","phonetic":"/ˈæb.rə.ɡeɪt/","phonetic_uk":"/ˈæb.rə.ɡeɪt/","phonetic_us":"/ˈæb.rə.ɡeɪt/","audio":null,"definition_vi":"bãi bỏ (luật lệ, thỏa thuận,...)","definition_en":"","examples":[{"example_en":"The rule has been abrogated by mutual consent.","example_vi":"The rule has been abrogated by mutual consent.","audio":null}],"image_url":"/media/vocabs_media/img/7_abrogate.jpg"},{"id":62,"word":"abrupt","pos":"adj","phonetic":"/əˈbrʌpt/","phonetic_uk":"/əˈbrʌpt/","phonetic_us":"/əˈbrʌpt/","audio":null,"definition_vi":"bất ngờ, đột ngột (một cách khó chịu)","definition_en":"","examples":[{"example_en":"an [abrupt] change/halt/departure","example_vi":"an abrupt change/halt/departure","audio":null}],"image_url":"/media/vocabs_media/img/7_abrupt.jpg"},{"id":63,"word":"abstemious","pos":"adj","phonetic":"/æbˈstiː.mi.əs/","phonetic_uk":"/æbˈstiː.mi.əs/","phonetic_us":"/æbˈstiː.mi.əs/","audio":null,"definition_vi":"tiết chế, có điều độ","definition_en":"","examples":[{"example_en":"He was a hard-working man with [abstemious] habits.","example_vi":"He was a hard-working man with abstemious habits.","audio":null}],"image_url":"/media/vocabs_media/img/6_abstemious.png"},{"id":64,"word":"accede","pos":"v","phonetic":"/əkˈsiːd/","phonetic_uk":"/əkˈsiːd/","phonetic_us":"/əkˈsiːd/","audio":null,"definition_vi":"đồng ý, tán thành một ý kiến, đề nghị,...","definition_en":"","examples":[{"example_en":"He acceded to demands for his resignation.","example_vi":"He acceded to demands for his resignation.","audio":null}],"image_url":"/media/vocabs_media/img/7_accede.jpg"},{"id":65,"word":"accentuate","pos":"v","phonetic":"/əkˈsentʃueɪt/","phonetic_uk":"/əkˈsentʃueɪt/","phonetic_us":"/əkˈsentʃueɪt/","audio":null,"definition_vi":"tô điểm, làm nổi bật","definition_en":"","examples":[{"example_en":"Her short hair accentuated her huge eyes.","example_vi":"Her short hair accentuated her huge eyes.","audio":null}],"image_url":"/media/vocabs_media/img/7_accentuate.jpg"},{"id":66,"word":"acclaim","pos":"v","phonetic":"/əˈkleɪm/","phonetic_uk":"/əˈkleɪm/","phonetic_us":"/əˈkleɪm/","audio":null,"definition_vi":"ca ngợi, tán dương","definition_en":"","examples":[{"example_en":"a highly/widely acclaimed performance","example_vi":"a highly/widely acclaimed performance","audio":null}],"image_url":"/media/vocabs_media/img/6_acclaim.png"},{"id":67,"word":"accolade","pos":"n","phonetic":"/ˈækəleɪd/","phonetic_uk":"/ˈækəleɪd/","phonetic_us":"/ˈækəleɪd/","audio":null,"definition_vi":"sự vinh danh/phần thưởng cho thành tựu mà mọi người ngưỡng mộ","definition_en":"","examples":[{"example_en":"There is no higher [accolade] at this school than an honorary degree.","example_vi":"There is no higher accolade at this school than an honorary degree.","audio":null}],"image_url":"/media/vocabs_media/img/6_accolade.jpg"},{"id":68,"word":"accord","pos":"n","phonetic":"/əˈkɔːd/","phonetic_uk":"/əˈkɔːd/","phonetic_us":"/əˈkɔːd/","audio":null,"definition_vi":"hiệp định, hiệp ước","definition_en":"","examples":[{"example_en":"The two sides signed a peace [accord] last July.","example_vi":"The two sides signed a peace accord last July.","audio":null}],"image_url":"/media/vocabs_media/img/7_accord.jpg"},{"id":69,"word":"acrimonious","pos":"adj","phonetic":"/ˌækrɪˈməʊniəs/","phonetic_uk":"/ˌækrɪˈməʊniəs/","phonetic_us":"/ˌækrɪˈməʊniəs/","audio":null,"definition_vi":"chua cay, gay gắt","definition_en":"","examples":[{"example_en":"His parents went through an [acrimonious] divorce.","example_vi":"His parents went through an acrimonious divorce.","audio":null}],"image_url":"/media/vocabs_media/img/6_acrimonious.jpg"},{"id":70,"word":"acumen","pos":"n","phonetic":"/ˈækjʊmən/","phonetic_uk":"/ˈækjʊmən/","phonetic_us":"/ˈækjʊmən/","audio":null,"definition_vi":"sự nhạy bén","definition_en":"","examples":[{"example_en":"business/commercial/financial [acumen]","example_vi":"business/commercial/financial acumen","audio":null}],"image_url":"/media/vocabs_media/img/6_acumen.png"},{"id":71,"word":"admonish","pos":"v","phonetic":"/ədˈmɒnɪʃ/","phonetic_uk":"/ədˈmɒnɪʃ/","phonetic_us":"/ədˈmɒnɪʃ/","audio":null,"definition_vi":"khiển trách, la rầy","definition_en":"","examples":[{"example_en":"She was admonished for chewing gum in class.","example_vi":"She was admonished for chewing gum in class.","audio":null}],"image_url":"/media/vocabs_media/img/6_admonish.jpg"},{"id":72,"word":"advent","pos":"n","phonetic":"/ˈædvent/","phonetic_uk":"/ˈædvent/","phonetic_us":"/ˈædvent/","audio":null,"definition_vi":"sự ra đời, sự xuất hiện","definition_en":"","examples":[{"example_en":"the [advent] of new technology","example_vi":"the advent of new technology","audio":null}],"image_url":"/media/vocabs_media/img/7_advent.jpg"},{"id":73,"word":"adversary","pos":"n","phonetic":"/ˈædvəsəri/","phonetic_uk":"/ˈædvəsəri/","phonetic_us":"/ˈædvəsəri/","audio":null,"definition_vi":"đối thủ","definition_en":"","examples":[{"example_en":"his old political [adversary]","example_vi":"his old political adversary","audio":null}],"image_url":"/media/vocabs_media/img/7_adversary.jpg"},{"id":74,"word":"adversity","pos":"n","phonetic":"/ədˈvɜːsəti/","phonetic_uk":"/ədˈvɜːsəti/","phonetic_us":"/ədˈvɜːsəti/","audio":null,"definition_vi":"nghịch cảnh","definition_en":"","examples":[{"example_en":"courage in the face of [adversity]","example_vi":"courage in the face of adversity","audio":null}],"image_url":"/media/vocabs_media/img/7_adversity.jpg"},{"id":75,"word":"affable","pos":"adj","phonetic":"/ˈæfəbl/","phonetic_uk":"/ˈæfəbl/","phonetic_us":"/ˈæfəbl/","audio":null,"definition_vi":"hoà nhã, dễ gần","definition_en":"","examples":[{"example_en":"He struck me as an [affable] sort of a man.","example_vi":"He struck me as an affable sort of a man.","audio":null}],"image_url":"/media/vocabs_media/img/6_affable.jpg"},{"id":76,"word":"affluent","pos":"adj","phonetic":"/ˈæfluənt/","phonetic_uk":"/ˈæfluənt/","phonetic_us":"/ˈæfluənt/","audio":null,"definition_vi":"giàu có","definition_en":"","examples":[{"example_en":"[affluent] Western countries","example_vi":"affluent Western countries","audio":null}],"image_url":"/media/vocabs_media/img/7_affluent.jpg"},{"id":77,"word":"aforementioned","pos":"adj","phonetic":"/əˈfɔːmenʃənd/","phonetic_uk":"/əˈfɔːmenʃənd/","phonetic_us":"/əˈfɔːmenʃənd/","audio":null,"definition_vi":"đã kể trước đây, đã nói ở trên","definition_en":"","examples":[{"example_en":"The [aforementioned] person was seen acting suspiciously.","example_vi":"The aforementioned person was seen acting suspiciously.","audio":null}],"image_url":"/media/vocabs_media/img/7_aforementioned.jpg"},{"id":78,"word":"aggravate","pos":"v","phonetic":"/ˈæɡrəveɪt/","phonetic_uk":"/ˈæɡrəveɪt/","phonetic_us":"/ˈæɡrəveɪt/","audio":null,"definition_vi":"làm trầm trọng thêm, làm nặng thêm","definition_en":"","examples":[{"example_en":"Pollution can [aggravate] asthma.","example_vi":"Pollution can aggravate asthma.","audio":null}],"image_url":"/media/vocabs_media/img/5_aggravate.jpg"},{"id":79,"word":"agitate","pos":"v","phonetic":"/ˈædʒɪteɪt/","phonetic_uk":"/ˈædʒɪteɪt/","phonetic_us":"/ˈædʒɪteɪt/","audio":null,"definition_vi":"tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội)","definition_en":"","examples":[{"example_en":"political groups agitating for social change","example_vi":"political groups agitating for social change","audio":null}],"image_url":"/media/vocabs_media/img/7_agitate.jpg"},{"id":80,"word":"alacrity","pos":"n","phonetic":"/əˈlækrəti/","phonetic_uk":"/əˈlækrəti/","phonetic_us":"/əˈlækrəti/","audio":null,"definition_vi":"sự sốt sắng","definition_en":"","examples":[{"example_en":"They accepted the offer with [alacrity].","example_vi":"They accepted the offer with alacrity.","audio":null}],"image_url":"/media/vocabs_media/img/6_alacrity.jpg"}]',  -- exercise_data (JSON)
    160,  -- exercise_duration (ước tính: 2 phút/từ)
    0,  -- pass_score
    0,  -- max_score
    FALSE,  -- is_free
    TRUE,  -- is_active
    0,  -- view_count
    NOW(),
    NOW()
);

-- Kiểm tra kết quả
SELECT 
    lesson_id,
    module_id,
    course_id,
    title,
    lesson_type,
    exercise_type,
    has_exercise,
    JSON_LENGTH(exercise_data) as total_flashcards
FROM lessons 
WHERE lesson_id = 70;
